#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2.5.0"
APP_VERSION="NOVA-2.5.0"
REV="CLEAN-REALTIME-CORE-R2-EMERGENCY"
ZIP_NAME="QUANT_NOVA_2.5.0_CLEAN_REALTIME_CORE_R2.zip"
ROOT_NAME="nova2500"
EXPECTED_ZIP_SHA256="a70b629bd7d308748c80bbc6022fd0af05cb7f4a77c9fd7b2bfee5147bd7f809"
APP_DIR="$HOME/quant-nova"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="3200"
IMAGE="quant-nova:2.5.0-clean-r2-${EXPECTED_ZIP_SHA256:0:12}"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="quant-nova-backup-clean250-${STAMP}"
FAILED="quant-nova-failed-clean250-${STAMP}"
CANDIDATE="quant-nova-candidate-${STAMP}"
TMP="$(mktemp -d)"
DEPLOY_DIR="$APP_DIR/deployments/clean250-$STAMP"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
GUARD_BK="$DEPLOY_DIR/http-guard-static-before"
CUTOVER=0
SUCCESS=0
GUARD_SYNCED=0
OLD_RENAMED=0

say(){ printf '
==> %s
' "$*"; }

on_exit(){
  ec=$?
  trap - EXIT
  # Candidate is disposable and never owns live data.
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  if [[ $SUCCESS -ne 1 && $CUTOVER -eq 1 ]]; then
    echo "[자동복구] CLEAN 2.5.0 cutover 실패 — 직전 정상 컨테이너 복구" >&2
    if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
      sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker rename "$CONTAINER" "$FAILED" >/dev/null 2>&1 || true
    fi
    if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
      sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
    fi
    if [[ $GUARD_SYNCED -eq 1 && -d "$GUARD_BK" ]]; then
      [[ -f "$GUARD_BK/index.html" ]] && sudo cp "$GUARD_BK/index.html" "$GUARD_STATIC/index.html" || true
      [[ -f "$GUARD_BK/nova.js" ]] && sudo cp "$GUARD_BK/nova.js" "$GUARD_STATIC/nova.js" || true
      sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$TMP" >/dev/null 2>&1 || true
  if [[ $SUCCESS -eq 1 ]]; then exit 0; else exit "${ec:-1}"; fi
}
trap on_exit EXIT

[[ "$(id -u)" -ne 0 ]] || { echo "ubuntu 사용자로 실행하세요." >&2; exit 1; }
mkdir -p "$DEPLOY_DIR"

say "0/8 배포 Gate — 정상판 보호 / 장애시 Emergency 허용"
KHM="$(TZ=Asia/Seoul date +%H%M)"
KH=$((10#${KHM:0:2})); KM=$((10#${KHM:2:2})); KMIN=$((KH*60+KM))
EMERGENCY="${NOVA_EMERGENCY_DEPLOY:-NO}"
if [[ $KMIN -ge 440 && $KMIN -lt 1210 && "$EMERGENCY" != "YES" ]]; then
  echo "배포 중단: KST $KHM 장중입니다." >&2
  echo "기존 앱이 실제로 작동하지 않는 경우에만 NOVA_EMERGENCY_DEPLOY=YES 로 실행하세요." >&2
  exit 2
fi
if [[ "$EMERGENCY" == "YES" ]]; then
  echo "EMERGENCY_DEPLOY=ENABLED — 기존 컨테이너는 삭제하지 않고 rollback용으로 보존"
fi

say "1/8 사전점검 — Key/Data 보호 + 기존 상태 진단"
for c in python3 curl sha256sum base64 awk df; do command -v "$c" >/dev/null 2>&1 || { echo "필수 명령 없음: $c" >&2; exit 1; }; done
command -v node >/dev/null 2>&1 || { echo "node 없음 — static JS syntax gate 불가" >&2; exit 1; }
sudo docker info >/dev/null 2>&1 || { echo "Docker daemon 접근 실패" >&2; exit 1; }
[[ -s "$APP_DIR/.env" ]] || { echo "$APP_DIR/.env 없음" >&2; exit 1; }
[[ -d "$APP_DIR/data" ]] || { echo "$APP_DIR/data 없음" >&2; exit 1; }
sudo docker inspect "$CONTAINER" >/dev/null 2>&1 || { echo "현재 quant-nova 컨테이너 없음 — 안전한 rollback 원본이 없어 중단" >&2; exit 1; }
FREE_KB="$(df -Pk "$HOME" | awk 'NR==2{print $4}')"; [[ ${FREE_KB:-0} -ge 1048576 ]] || { echo "디스크 여유 1GB 미만" >&2; exit 1; }
# Existing release health is diagnostic. In emergency mode a broken baseline must not block a fully shadow-tested replacement.
if curl -fsS --connect-timeout 2 --max-time 5 "http://127.0.0.1:${HOST_PORT}/api/health" >/dev/null 2>&1; then
  echo "ACTIVE_BASELINE_HEALTH=PASS"
else
  echo "ACTIVE_BASELINE_HEALTH=FAIL" >&2
  if [[ "$EMERGENCY" != "YES" ]]; then
    echo "기존 앱 health 실패 — 일반 배포 중단. 장애 복구 목적이면 NOVA_EMERGENCY_DEPLOY=YES 로 실행" >&2
    exit 1
  fi
  echo "EMERGENCY_CONTINUE=YES — Candidate 검증 전에는 기존 컨테이너를 건드리지 않음"
fi

say "2/8 CLEAN 원본 복원 + SHA + Manifest"
base64 -d > "$TMP/$ZIP_NAME" <<'NOVA250_PAYLOAD'
UEsDBBQAAAAIAHoBDF3BJlIkcgUAAHcIAAAkAAAAbm92YTI1MDAvQVJDSElURUNUVVJFX0NMRUFO
XzIuNS4wLm1kbVVdUxpJFH3nV9yqvLHKJNm1tipvIxBDBRgyjF9PGyITnQowLB+buE9oJhaKlmaF
