say "7/8 Final livez/realtime soak + WS contract"
LIVE_OK=0
for i in $(seq 1 100); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.0" and j.get("candidate_mode") is False and j.get("realtime_running") else 1)' 2>/dev/null; then LIVE_OK=1;break;fi
  sleep .25
done
[[ $LIVE_OK -eq 1 ]] || { sudo docker logs --tail 300 "$CONTAINER" || true; echo "final livez 실패" >&2; exit 1; }
for i in $(seq 1 40); do
  curl -fsS -o /dev/null --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" || { echo "final liveness soak fail $i" >&2; exit 1; }
  sleep .15
done
RH="$(curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/realtime-health")"
printf '%s' "$RH" | python3 -c 'import sys,json;j=json.load(sys.stdin);assert j.get("ok") is True,(j.get("status"),j.get("faults"));assert int((j.get("lane") or {}).get("critical_overflow_events") or 0)==0;assert int((j.get("lane") or {}).get("handler_errors") or 0)==0;print("FINAL_RT_HEALTH=PASS",j.get("status"))'
WC="$(curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/ws-contract")"
printf '%s' "$WC" | python3 -c 'import sys,json;j=json.load(sys.stdin);c=j.get("contract") or {};assert (c.get("trade_type"),c.get("program_type"),c.get("orderbook_type"))==("0B","0u","0D"),c;print("WS_CONTRACT=PASS 0B/0u/0D")'

say "8/8 Public UI sync + deployment seal"
if [[ -d "$GUARD_STATIC" ]]; then
  sudo cp "$ROOT/static/index.html" "$GUARD_STATIC/.index.html.clean250.tmp"
  sudo cp "$ROOT/static/nova.js" "$GUARD_STATIC/.nova.js.clean250.tmp"
  sudo chmod 644 "$GUARD_STATIC/.index.html.clean250.tmp" "$GUARD_STATIC/.nova.js.clean250.tmp"
  sudo mv "$GUARD_STATIC/.index.html.clean250.tmp" "$GUARD_STATIC/index.html"
  sudo mv "$GUARD_STATIC/.nova.js.clean250.tmp" "$GUARD_STATIC/nova.js"
  sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  GUARD_SYNCED=1
fi
MAIN_SHA="$(sudo docker exec "$CONTAINER" sha256sum /app/app/main.py | awk '{print $1}')"
{
  echo "status=PASS"
  echo "version=$APP_VERSION"
  echo "rev=$REV"
  echo "zip_sha256=$EXPECTED_ZIP_SHA256"
  echo "main_sha256=$MAIN_SHA"
  echo "image=$IMAGE"
  echo "backup=$BACKUP"
  echo "deployed_at=$(date -Is)"
  echo "candidate_soak=PASS"
  echo "final_livez_soak=PASS"
  echo "critical_overflow=0"
  echo "handler_errors=0"
  echo "build_context_check=PASS"
  echo "policy=CLEAN_REALTIME_CORE_R2"
} > "$DEPLOY_DIR/DEPLOYMENT_PASS.txt"
SUCCESS=1

echo
echo "=============================================="
echo " QUANT NOVA 2.5.0 CLEAN REALTIME CORE R2 PASS"
echo " active=$CONTAINER"
echo " backup=$BACKUP"
echo " image=$IMAGE"
echo " deploy_record=$DEPLOY_DIR/DEPLOYMENT_PASS.txt"
echo "=============================================="
